"use client";

import { FormEvent, useEffect, useState } from "react";
import { CircleDollarSign, ClipboardList, LogOut, PackageOpen, Settings, Store, Truck } from "lucide-react";
import { Logo } from "@/components/brand/Logo";
import { authenticatedFetch } from "@/lib/supabase/fetch";
import { createBrowserSupabaseClient } from "@/lib/supabase/browser";

type VendorData = { vendor: { business_name: string; email: string | null; phone: string | null; website_url: string | null; description: string | null; address: string | null; city: string; state: string; postal_code: string | null; active: boolean; stripe_account_id: string | null; stripe_details_submitted: boolean; stripe_charges_enabled: boolean; stripe_payouts_enabled: boolean }; products: Array<{ id: string; name: string; category: string; customer_price: number; active: boolean }>; orders: Array<{ id: string; status: string; delivery_date: string; customer_amount: number; delivery_fee: number }> };

export function VendorDashboard({ onboarding = false }: { onboarding?: boolean }) {
  const [data, setData] = useState<VendorData | null>(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  useEffect(() => { authenticatedFetch("/api/vendor/workspace", { cache: "no-store" }).then(async (response) => { const result = await response.json() as VendorData & { error?: string }; if (!response.ok) throw new Error(result.error); setData(result); }).catch((reason) => setError(reason instanceof Error ? reason.message : "Unable to load vendor workspace.")); }, []);
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); setError(""); const body = Object.fromEntries(new FormData(event.currentTarget)); try { const response = await authenticatedFetch("/api/vendor/workspace", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error); location.href = "/vendor"; } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to save vendor profile."); setBusy(false); } }
  async function signOut() { await createBrowserSupabaseClient().auth.signOut(); location.href = "/login"; }
  const vendor = data?.vendor;
  if (!data) return <main className="vendor-loading"><Logo /><p>{error || "Opening your vendor workspace…"}</p></main>;
  if (onboarding || !vendor?.description) return <main className="vendor-onboarding"><header><Logo /><span>PerkJoy Local partner setup</span></header><section><h1>Tell customers what makes your business special.</h1><p>Set up your storefront and service area. Employee moments and celebration rules are handled by business clients, so you won’t be asked about them.</p>{error && <div className="app-error">{error}</div>}<form onSubmit={save}><div className="form-grid"><label>Business name<input name="businessName" required defaultValue={vendor?.business_name} /></label><label>Contact email<input name="email" type="email" defaultValue={vendor?.email ?? ""} /></label></div><label>Business description<textarea name="description" required rows={4} defaultValue={vendor?.description ?? ""} placeholder="What do you make or deliver?" /></label><div className="form-grid"><label>Phone<input name="phone" defaultValue={vendor?.phone ?? ""} /></label><label>Website<input name="websiteUrl" type="url" defaultValue={vendor?.website_url ?? ""} /></label></div><label>Street address<input name="address" defaultValue={vendor?.address ?? ""} /></label><div className="form-grid three"><label>City<input name="city" required defaultValue={vendor?.city ?? ""} /></label><label>State<input name="state" required maxLength={2} defaultValue={vendor?.state ?? ""} /></label><label>ZIP<input name="postalCode" defaultValue={vendor?.postal_code ?? ""} /></label></div><button className="button button-primary" disabled={busy}>{busy ? "Saving…" : "Open vendor dashboard"}</button></form></section></main>;
  if (!data) return null;
  const payoutReady = vendor.stripe_charges_enabled && vendor.stripe_payouts_enabled;
  return <main className="vendor-shell"><aside><Logo /><nav><a className="active" href="#overview"><Store />Overview</a><a href="#orders"><ClipboardList />Orders</a><a href="#catalog"><PackageOpen />Catalog</a><a href="#payouts"><CircleDollarSign />Payouts</a><a href="/onboarding"><Settings />Business profile</a></nav><button onClick={signOut}><LogOut />Sign out</button></aside><section><header><div><h1>{vendor.business_name}</h1><p>Your PerkJoy Local partner workspace.</p></div><span className={vendor.active ? "ready" : "pending"}>{vendor.active ? "Marketplace active" : "Pending review"}</span></header>{error && <div className="app-error">{error}</div>}<div className="vendor-kpis"><article><ClipboardList /><span><b>{data.orders.length}</b><small>Total orders</small></span></article><article><Truck /><span><b>{data.orders.filter((order) => order.status === "paid").length}</b><small>Ready to fulfill</small></span></article><article><PackageOpen /><span><b>{data.products.length}</b><small>Catalog items</small></span></article><article><CircleDollarSign /><span><b>{payoutReady ? "Ready" : "Setup needed"}</b><small>Stripe payouts</small></span></article></div><section id="orders" className="vendor-panel"><h2>Recent orders</h2>{data.orders.length ? data.orders.map((order) => <article key={order.id}><span><b>Delivery {order.delivery_date}</b><small>Order {order.id.slice(0, 8)}</small></span><em>{order.status.replaceAll("_", " ")}</em><strong>${Number(order.customer_amount + order.delivery_fee).toFixed(2)}</strong></article>) : <div className="vendor-empty"><ClipboardList /><b>No orders yet</b><p>New PerkJoy Local orders will appear here.</p></div>}</section><section id="catalog" className="vendor-panel"><h2>Your catalog</h2>{data.products.length ? data.products.map((product) => <article key={product.id}><span><b>{product.name}</b><small>{product.category}</small></span><em>{product.active ? "Active" : "Draft"}</em><strong>${Number(product.customer_price).toFixed(2)}</strong></article>) : <div className="vendor-empty"><PackageOpen /><b>No products yet</b><p>Catalog management is the next step for your local storefront.</p></div>}</section></section></main>;
}
